-- Per-store vendor access control (Phase 1).
--
-- Links Supabase Auth users to the store(s) they may operate. Enforced by
-- backend/middleware/requireVendorAccess.js once ENFORCE_VENDOR_SCOPING=true.
--
-- Assumes vendors.id is uuid (it is generated by the database in seed.js and
-- treated as a uuid by the frontend). Check against the baseline dump before
-- applying; if vendors.id is another type, change vendor_id below to match.
-- Idempotent: safe to run more than once.

create table if not exists public.vendor_users (
  user_id    uuid not null references auth.users (id) on delete cascade,
  vendor_id  uuid not null references public.vendors (id) on delete cascade,
  role       text not null default 'staff' check (role in ('owner', 'staff')),
  created_at timestamptz not null default now(),
  primary key (user_id, vendor_id)
);

create index if not exists vendor_users_vendor_id_idx on public.vendor_users (vendor_id);

-- The API uses the service-role key (bypasses RLS). RLS still protects this
-- table from the public anon key; signed-in users may read only their own links.
alter table public.vendor_users enable row level security;

drop policy if exists "vendor_users: read own links" on public.vendor_users;
create policy "vendor_users: read own links"
  on public.vendor_users for select
  to authenticated
  using (user_id = auth.uid());
